def _get_statements_matching_principal(
    self, request, statements: List[dict]
) -> List[dict]:
    user = request.user
    user_roles = None
    matched = []

    for statement in statements:
        principals = statement["principal"]
        found = False

        if "*" in principals:
            found = True
        elif "admin" in principals:
            found = user.is_superuser
        elif "staff" in principals:
            found = user.is_staff
        elif "authenticated" in principals:
            found = not user.is_anonymous
        elif "anonymous" in principals:
            found = user.is_anonymous
        elif self.id_prefix + str(user.pk) in principals:
            found = True
        else:
            if not user_roles:
                user_roles = self.get_user_group_values(user)

            for user_role in user_roles:
                if self.group_prefix + user_role in principals:
                    found = True
                    break

        if found:
            matched.append(statement)

    return matched

def guarded_connect(inst: socket.socket, *args: Any) -> None:
    host = host_from_connect_args(args)
    if host in allowed_ip_hosts_and_hostnames or (
        _is_unix_socket(inst.family) and allow_unix_socket
    ):
        return _true_connect(inst, *args)

    if host and networks and is_ipaddress(host):
        ip = ipaddress.ip_address(host)
        if any(ip in net for net in networks):
            return _true_connect(inst, *args)

    raise SocketConnectBlockedError(allowed_list, host)

def cache(timeout, key_func=None):
    """Caches a function results for timeout seconds."""
    if isinstance(timeout, int):
        timeout = timedelta(seconds=timeout)

    if key_func is None:
        key_func = lambda *a, **kw: a + tuple(sorted(kw.items())) if kw else a

    def decorator(func):
        cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = key_func(*args, **kwargs)
            if key in cache:
                result, timestamp = cache[key]
                if datetime.now() - timestamp < timeout:
                    return result
                else:
                    del cache[key]

            result = func(*args, **kwargs)
            cache[key] = result, datetime.now()
            return result

        def invalidate(*args, **kwargs):
            cache.pop(key_func(*args, **kwargs))
        wrapper.invalidate = invalidate

        def invalidate_all():
            cache.clear()
        wrapper.invalidate_all = invalidate_all

def fake_time():
    if _should_use_real_time():
        return real_time()
    current_time = get_current_time()
    return calendar.timegm(current_time.timetuple()) + current_time.microsecond / 1000000.0

if _TIME_NS_PRESENT:
    def fake_time_ns():
        if _should_use_real_time():
            return real_time_ns()
        return int(int(fake_time()) * 1e9)
